    # If a vertical 5-line is present, it divides the left/right fill regions.
    hrows = [r for r in range(h) if sum(v == 5 for v in grid[r]) >= 3]
    vcols = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= 3]
    if hrows and vcols:
        # Intersecting L: use each row's left marker for fill to the vertical bar.
        vc = max(vcols)
        for r in range(h):
            marker = grid[r][0]
            if marker not in (0, 5) and grid[r][vc] == 5:
                for c in range(1, vc):
                    out[r][c] = marker
        # Right of the vertical line, copy each row's seed color across that horizontal run.
        for r in range(h):
            seed = next((c for c in range(vc + 1, w) if grid[r][c] not in (0, 5)), None)
            if seed is not None:
                color = grid[r][seed]
                for c in range(vc + 1, w):
                    out[r][c] = color
        # If a horizontal colored template intersects a stem, propagate its profile along stem.
        stem = [r for r in range(h) if grid[r][vc] == 5]
        seedrow = next((r for r in stem if any(grid[r][c] not in (0,5) for c in range(w))), None)
        if seedrow is not None:
            for r in stem:
                for c in range(w):
                    if grid[seedrow][c] not in (0,5): out[r][c] = grid[seedrow][c]
    elif hrows:
        # Horizontal 5 frame with left-hand marker colors: replicate each marker across its row.
        hr = hrows[0]
        cols = [c for c,v in enumerate(grid[hr]) if v == 5]
        left, right = min(cols), max(cols)
        for r in range(h):
