def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    hrows = [r for r in range(h) if sum(v == 5 for v in grid[r]) >= 3]
    vcols = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= 3]

    # Horizontal guide: markers on its left edge expand across each contiguous run.
    for r5 in hrows:
        cols = [c for c, v in enumerate(grid[r5]) if v == 5]
        runs = []
        for c in cols:
            if not runs or c != runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        for run in runs:
            left, right = run[0], run[-1]
            for r in range(h):
                mark = grid[r][left]
                if mark not in (0, 5):
                    for c in range(left + 1, right + 1):
                        out[r][c] = mark

    # Vertical guide: profiles on its right are repeated along the stem.
    for vc in vcols:
        stem = [r for r in range(h) if grid[r][vc] == 5]
        samples = [r for r in range(h)
                   if any(grid[r][c] not in (0, 5) for c in range(vc + 1, w))]
        if samples:
            # Include sample rows at the endpoint as part of the repeated sequence.
            samples.sort()
            targets = sorted(set(stem + samples))
            first_target = min(targets)
            # If there is a horizontal header crossing the stem, leave that header row intact.
            header = next((r for r in hrows if grid[r][vc] == 5), None)
            for r in targets:
                if r == header:
                    continue
                phase = r - first_target
                source = grid[samples[phase % len(samples)]]
                for c in range(vc + 1, w):
                    if source[c] not in (0, 5):
                        out[r][c] = source[c]
            # Continue the 5 guide through any sample row directly beyond its endpoint.
            for r in samples:
                if r == max(stem) + 1 and all(grid[k][vc] == 5 for k in range(min(stem), max(stem)+1)):
                    out[r][vc] = 5
    return out
