        cols = [c for c, v in enumerate(grid[r5]) if v == 5]
        runs = []
        for c in cols:
            if not runs or c > runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        for run in runs:
            if len(run) < 3:
                continue
            left, right = run[0], run[-1]
            for r in range(h):
                marker = grid[r][left]
                if marker not in (0, 5):
                    for c in range(left + 1, right + 1):
                        out[r][c] = marker
    # Vertical 5-lines repeat adjacent colored horizontal profiles along the line.
    for vc in range(w):
        stem = [r for r in range(h) if grid[r][vc] == 5]
        if len(stem) < 3:
            continue
        profiles = [r for r in range(h)
                    if any(grid[r][c] not in (0, 5) for c in range(vc + 1, w))]
        if not profiles:
            continue
        profiles.sort()
        # Prefer the two bottommost color examples when they form the seed pattern.
        seeds = profiles[-2:] if len(profiles) >= 2 else profiles
        header = next((r for r in range(h)
                       if sum(v == 5 for v in grid[r]) >= 3 and grid[r][vc] == 5), None)
        targets = sorted(set(stem + [r for r in seeds if r == max(stem) + 1]))
        origin = header + 1 if header is not None else min(stem)
        for r in targets:
            if r == header:
                continue
